ch10/01-gradient/stop-rule.solution:
def descend(lr, tol=1e-6, max_steps=10000):
    w, prev = 0.0, loss(0.0)
    for step in range(1, max_steps + 1):
        w = w - lr * grad(w)
        cur = loss(w)
        if abs(prev - cur) < tol:
            return w, step
        prev = cur
    return w, max_steps

steps, w_found = {}, {}
for lr in [0.001, 0.01, 0.03]:
    w, n = descend(lr)
    steps[lr], w_found[lr] = n, round(float(w), 4)
with np.errstate(all="ignore"):         # переполнение при lr = 0.1 ожидаемо
    w_01, steps_01 = descend(0.1)
print(steps, w_found, steps_01, w_01)

